package cz.mh.rallye.rallye_backend.simulation.application;
import java.time.Instant;import java.util.*;import cz.mh.rallye.rallye_backend.competition.domain.*;import static cz.mh.rallye.rallye_backend.competition.domain.RaceEvaluator.*;import cz.mh.rallye.rallye_backend.simulation.persistence.SimulationStore.Session;import cz.mh.rallye.rallye_backend.templates.application.*;
/** Explicit safe participant/dashboard projection. Never serialize Definition/StageConfiguration here. */
public final class SimulationView {
 private SimulationView(){}
 public record Source(UUID templateId,long templateVersion,String templateName){}
 public record ClockView(Instant virtualStartAt,Instant virtualNow,long elapsedSimulationMs,Long activeStageElapsedMs,Instant timeFloor,boolean clockBeforeState,boolean businessActionsAllowed){}
 public record GpsPreview(double distanceMeters,boolean withinPerimeter,boolean accuracyUsable){}
 public record TimeRule(boolean enabled,Long intervalSeconds,String pointsPerInterval){}
 public record DelayRule(boolean enabled,Long minimumDurationMs,String pointsPerSecond){}
 public record SkipPreview(String replacementPoints,String currentEffectivePoints,String pointsDeltaIfSkipped){}
 public record ParticipantStage(UUID id,int sequenceNo,String name,String instructionsMarkdown,String instructionsRenderedHtml,Instant activatedAt,Long expectedDurationMs,List<String> requiredChecks,List<String> satisfiedChecks,TimeRule timePenalty,DelayRule delayed,SkipPreview skipPreview){}
 public record Cause(String cause,String points){}public record StageScore(UUID stageId,int sequenceNo,String status,String points){}
 public record PenaltyView(UUID id,UUID actionId,UUID stageId,String cause,String points,boolean effective,UUID supersededBy,Instant virtualAt){}
 public record ActionView(UUID actionId,long sequence,String type,UUID stageId,String outcome,String pointsDelta,Instant virtualAt,GpsResult gps){}
 public record Dashboard(String totalPenaltyPoints,long completedStages,long skippedStages,int totalStages,UUID currentStageId,List<Cause> byCause,List<StageScore> byStage,ActionView lastAction,List<PenaltyView> recentPenalties,boolean hasMorePenaltyHistory){}
 public record View(UUID id,UUID runId,long version,String status,Source source,ClockView clock,Position position,GpsPreview gpsPreview,ParticipantStage currentStage,Dashboard dashboard,Instant expiresAt){}
 public static ActionView action(Action a){return a==null?null:new ActionView(a.actionId(),a.sequence(),a.type(),a.stageId(),a.outcome(),Long.toString(a.pointsDelta()),a.virtualAt(),a.gps());}
 public static PenaltyView penalty(Penalty p){return new PenaltyView(p.id(),p.actionId(),p.stageId(),p.cause(),Long.toString(p.points()),p.effective(),p.supersededBy(),p.virtualAt());}
 private static String points(Long p){return p==null?null:p.toString();}
 public static View of(Session session,Map<String,String> names){var state=session.state();var active=state.status().equals("RUNNING")?current(state):null;Stage def=active==null?null:session.definition().stages().stream().filter(s->s.id().equals(active.stageId())).findFirst().orElseThrow();boolean past=state.virtualNow().isBefore(state.timeFloor());Long elapsed=active==null||state.virtualNow().isBefore(active.activatedAt())?null:duration(active.activatedAt(),state.virtualNow());var clock=new ClockView(state.virtualStartAt(),state.virtualNow(),duration(state.virtualStartAt(),state.virtualNow()),elapsed,state.timeFloor(),past,state.status().equals("RUNNING")&&!past);
  ParticipantStage stage=null;GpsPreview preview=null;if(def!=null){var c=def.configuration();var required=new ArrayList<String>();var satisfied=new ArrayList<String>();if(c.gps().enabled())required.add("GPS");if(c.code().enabled())required.add("CODE");if(active.gpsSatisfied())satisfied.add("GPS");if(active.codeSatisfied())satisfied.add("CODE");long replacement=add(def.maxPenaltyPoints()==null?0:def.maxPenaltyPoints(),session.definition().skipPenaltyPoints()),previous=stagePoints(state,def.id());stage=new ParticipantStage(def.id(),def.sequenceNo(),def.name(),def.instructionsMarkdown(),InstructionsMarkdown.renderSimulation(session.id(),def.instructionsMarkdown(),names),active.activatedAt(),def.expectedDurationMs(),List.copyOf(required),List.copyOf(satisfied),new TimeRule(c.timePenalty().enabled(),c.timePenalty().intervalMs()==null?null:c.timePenalty().intervalMs()/1000,points(c.timePenalty().pointsPerInterval())),new DelayRule(c.delayed().enabled(),c.delayed().minimumDurationMs(),points(c.delayed().pointsPerSecond())),new SkipPreview(Long.toString(replacement),Long.toString(previous),Long.toString(delta(replacement,previous))));if(state.position()!=null&&c.gps().enabled()){var p=state.position();double distance=GpsMath.distance(p.latitude(),p.longitude(),c.gps().latitude(),c.gps().longitude());preview=new GpsPreview(distance,distance<=c.gps().radiusMeters(),p.accuracyMeters()<=c.gps().radiusMeters());}}
  var causes=new TreeMap<String,Long>();for(var p:state.penalties())if(p.effective())causes.merge(p.cause(),p.points(),RaceEvaluator::add);var byCause=causes.entrySet().stream().map(e->new Cause(e.getKey(),e.getValue().toString())).toList();var scores=new ArrayList<StageScore>();for(int i=0;i<state.stages().size();i++){var p=state.stages().get(i);scores.add(new StageScore(p.stageId(),session.definition().stages().get(i).sequenceNo(),p.status(),Long.toString(stagePoints(state,p.stageId()))));}int first=Math.max(0,state.penalties().size()-50);var dashboard=new Dashboard(Long.toString(total(state)),state.stages().stream().filter(p->p.status().equals("COMPLETED")).count(),state.stages().stream().filter(p->p.status().equals("SKIPPED")).count(),state.stages().size(),active==null?null:active.stageId(),byCause,List.copyOf(scores),action(state.lastAction()),state.penalties().subList(first,state.penalties().size()).stream().map(SimulationView::penalty).toList(),first>0);
  return new View(session.id(),session.runId(),session.version(),state.status(),new Source(session.templateId(),session.templateVersion(),session.templateName()),clock,state.position(),preview,stage,dashboard,session.expiresAt());
 }
}
